-- Since 073b the runner executes stock_vs_charge and reads ct_settings (its own policy): 057's comment "only
-- service_role gets it" and 073's "reads ct_settings as its owner" describe the state before 073b (PR #105).
-- After it: 071_plan_schema_verify.sql shows policies = 5 (expected from 073b on; it was 0 by design of 071), and
-- 072b's verify still shows auditor_policy = 1 (rt_vehicle_segments keeps its own policy, untouched here).
-- REVERSE: 073b_plan_monitoring_rollback.sql (before 073's rollback: 073's refuses while B-78..B-90, B-94 exist).
-- EXPECTED: NOTICE "073b OK: 17 checks (14 of F3 + 3 of 072b, 16 enabled), 5 read policies on v5 + 1 on ct_settings, X read by the runner, every check 0 today".

DO $do$
DECLARE
  v_k int; v_trg0 int; v_g record; v_v numeric; v_sql text; v_ids text; v_a text[];
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  -- 0. GUARDS (order 072 -> 072b -> 073 -> 073b)
  IF to_regclass('public.ct_v_v5_revenue') IS NULL OR to_regprocedure('public.plan_h_pallet_sync(bigint[],text,text)') IS NULL THEN
    RAISE EXCEPTION '073b: 073 must be applied first';
  END IF;
  -- B-91..B-93 read rt_vehicle_segments through 072b's own policy: without it they would be blind (principle 1)
  IF to_regclass('public.rt_vehicle_segments') IS NULL OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public'
       AND tablename = 'rt_vehicle_segments' AND policyname = 'monitor_read' AND cmd = 'SELECT') THEN
    RAISE EXCEPTION '073b: 072b (rt_vehicle_segments and its monitor_read policy) must be applied first';
  END IF;
  IF EXISTS (SELECT 1 FROM monitoring.checks WHERE id IN ('B-78', 'B-79', 'B-80', 'B-81', 'B-82', 'B-83', 'B-84', 'B-85', 'B-86', 'B-87', 'B-88', 'B-89', 'B-90', 'B-94', 'B-91', 'B-92', 'B-93')) THEN
    RAISE EXCEPTION '073b: already applied (a check B-78..B-94 exists) - stop, re-measure';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('shipments', 'shipment_pieces', 'rt_stops', 'piece_legs', 'plan_notices')) THEN
    RAISE EXCEPTION '073b: a policy already exists on a v5 table - stop, re-measure';
  END IF;
  IF has_table_privilege('tms_check_runner', 'public.ct_settings', 'SELECT') THEN
    RAISE EXCEPTION '073b: the runner already reads ct_settings - stop, re-measure';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'ct_settings') THEN
    RAISE EXCEPTION '073b: a policy already exists on ct_settings - stop, re-measure';
  END IF;
  IF has_function_privilege('tms_check_runner', 'public.stock_vs_charge(numeric, numeric)', 'EXECUTE') THEN
    RAISE EXCEPTION '073b: the runner already executes stock_vs_charge (a grant, PUBLIC or a membership) - stop, re-measure';
  END IF;
