  -- 1. THE AUDITOR READS THE v5 TABLES (D-14). 071 left them RLS on, no policy: the grants to tms_check_runner and
  --    tms_reader give 0 rows, so a v5 check would be green for ever (principle 1). The same read-only policy as
  --    every table the auditor reads (050, 057's stock_lots, 072b's rt_vehicle_segments); service_role bypasses RLS.
  CREATE POLICY monitor_read ON public.shipments FOR SELECT TO tms_check_runner, tms_reader USING (true);
  CREATE POLICY monitor_read ON public.shipment_pieces FOR SELECT TO tms_check_runner, tms_reader USING (true);
  CREATE POLICY monitor_read ON public.rt_stops FOR SELECT TO tms_check_runner, tms_reader USING (true);
  CREATE POLICY monitor_read ON public.piece_legs FOR SELECT TO tms_check_runner, tms_reader USING (true);
